def lit(sql: str, indent: int) -> str:
    """A Python expression: the SQL as implicitly concatenated literals, wrapped."""
    width = 96 - indent - 2
    parts = textwrap.wrap(sql, width=width, break_long_words=False, drop_whitespace=False)
    # keep spaces at the end of each piece
    pad = " " * indent
    if len(parts) == 1:
        return f'"{parts[0]}"'
    return ("\n" + pad).join(f'"{p}"' for p in parts)


def tuple_of(sqls: list[str]) -> str:
    out = "(\n"
    for sql in sqls:
        out += "    " + lit(sql, 4) + ",\n"
    return out + ")"


def const(name: str, sql: str) -> str:
    if len(name) + 3 + len(sql) + 2 <= 100:
        return f'{name} = "{sql}"\n'
    return f"{name} = (\n    " + lit(sql, 4) + "\n)\n"


def header(doc: str, imports: str) -> str:
